INSERT INTO major (university_id, major_code, major_name, major_group, subject_req, major_note, duration, tuition) VALUES
  (1831, '10', '法学', '（103）', '{"track": "物理类", "subjects": ["物理"], "reselect": "不限"}', NULL, '四年', 5000.0),
  (1831, '5', '历史学', '（304）', '{"track": "历史类", "subjects": ["历史"], "reselect": "不限"}', '（国家专项）', '四年', 5000.0),
  (2674, '29', '物理学类', '（101）', '{"track": "物理类", "subjects": ["物理"], "reselect": "化学"}', '（教育部基础学科拔尖学生培养基地，中国科学院基础和前沿交叉学科贯通培养工程实施基地，国家级一流本科专业建设点。含严济慈物理科技英才班、王绶琯天文英才班等12个科技英才班；依托合肥国家实验室等多个国家级科研平台；含哈佛大学等多个海外交流项目资助。包含专业:物理学、应用物理学、天文学、光电信息科学与工程）', '四年', 4800.0),
  (2674, '22', '工科试验班', '（101）', '{"track": "物理类", "subjects": ["物理"], "reselect": "化学"}', '（航空航天、人形机器人、低碳能源技术及安全）（教育部基础学科拔尖学生培养基地，中国科学院基础和前沿交叉学科贯通培养工程实施基地，国家一流本科专业建设点。含钱学森力学科技英才班、吴仲华工程热物理英才班、新能源英才班、精密光机电与环境科技英才班。学校资助学生前往斯坦福大学、加州大学等高校开展国际交流。包含专业:机器人工程、理论与应用力学、机械设计制造及其自动化、测控技术与仪器、能源与动力工程、安全工程）', '四年', 4800.0),
  (2674, '15', '电子信息类', '（101）', '{"track": "物理类", "subjects": ["物理"], "reselect": "化学"}', '（信息科技方向）（国家级一流本科专业建设点。含信息科技英才、王大珩科技英才班。依托类脑智能技术及应用国家工程实验室、语音及语言信息处理国家工程研究中心等国家级科研平台进行培养；含学校资助斯坦福大学、华盛顿大学、帝国理工学院等国际交流项目。包含专业:电子信息工程、自动化）', '四年', 4800.0),
  (2674, '31', '计算机类', '（101）', '{"track": "物理类", "subjects": ["物理"], "reselect": "化学"}', '（教育部基础学科拔尖学生培养基地，国家一流本科专业建设点。依托认知智能全国重点实验室、国家高性能计算中心（合肥）等多个国家级科研平台进行培养；含学校资助斯坦福大学、华盛顿大学、帝国理工学院等国际交流项目。包含专业:计算机科学与技术）', '四年', 4800.0),
  (2674, '27', '化学类', '（101）', '{"track": "物理类", "subjects": ["物理"], "reselect": "化学"}', '（教育部基础学科拔尖学生培养基地，中国科学院基础和前沿交叉学科贯通培养工程实施基地，国家级一流本科专业建设点。依托国家级科研平台及中国科学院各科教融合单位开展合作培养；含哈佛大学、加州大学伯克利分校、麻省理工学院、普林斯顿大学、耶鲁大学等海外交流项目资助。包含专业:化学）', '四年', 4800.0),
  (2674, '16', '理科试验班类', '（101）', '{"track": "物理类", "subjects": ["物理"], "reselect": "化学"}', '（拔尖计划科技英才班）（包含专业:数学类（华罗庚数学科技英才班）、物理学类（严济慈物理科技英才班））', '四年', 4800.0),
  (2674, '32', '网络空间安全', '（101）', '{"track": "物理类", "subjects": ["物理"], "reselect": "化学"}', '（国家级一流本科专业建设点。含王小谟网络空间科技英才班（与中国电子科技集团合办）；依托合肥国家实验室、未来网络国家基础设施合肥中心等国家级科研平台，以及国家级实验教学平台，开展网络空间安全学科建设和人才培养）', '四年', 4800.0),
  (2674, '30', '数学类', '（101）', '{"track": "物理类", "subjects": ["物理"], "reselect": "化学"}', '（教育部基础学科拔尖学生培养基地，中国科学院基础和前沿交叉学科贯通培养工程实施基地，国家级一流本科专业建设点。含华罗庚数学科技英才班、中法数学英才班；含学校资助斯坦福大学、耶鲁大学、牛津大学、剑桥大学、巴黎高等师范学校等交流项目。包含专业:数学与应用数学、信息与计算科学）', '四年', 4800.0),
